step.code:
await page.getByLabel('Email').fill('user@example.com');
await page.getByLabel('Password').fill('test-password-123');
await page.screenshot({ path: 'evidence/auth-flow/02-form-filled.png' });
await page.getByRole('button', { name: 'Sign In' }).click();

// Wait for auth redirect to complete
await page.waitForURL('**/dashboard', { timeout: 30000 });
await page.screenshot({ path: 'evidence/auth-flow/03-post-login.png' });

const cookies = await context.cookies();
const localStorage = await page.evaluate(() => {
  return {
    token: localStorage.getItem('auth_token'),
    refresh: localStorage.getItem('refresh_token'),
  };
});

// Baseline: current production or known-good version
await page.goto('https://example.com', { waitUntil: 'networkidle' });
await page.screenshot({ path: 'evidence/visual-regression/baseline.png', fullPage: true });

// Candidate: the version under test (staging, localhost, feature branch)
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
await page.screenshot({ path: 'evidence/visual-regression/candidate.png', fullPage: true });

// Compare computed styles of key elements
const baselineStyles = await baselinePage.evaluate(() => {
  const el = document.querySelector('.hero-title');
  return {
    fontSize: getComputedStyle(el).fontSize,
    color: getComputedStyle(el).color,
    marginTop: getComputedStyle(el).marginTop,
  };
});
const candidateStyles = await candidatePage.evaluate(() => {
  const el = document.querySelector('.hero-title');
  return {
    fontSize: getComputedStyle(el).fontSize,
    color: getComputedStyle(el).color,
    marginTop: getComputedStyle(el).marginTop,
  };
});

// Collect all API responses
const apiResponses = [];
page.on('response', async (response) => {
  const url = response.url();
  if (url.includes('/api/')) {
    const body = await response.body();
    apiResponses.push({
      url,
      status: response.status(),
      headers: response.headers(),
      body: body.slice(0, 5000), // truncate large bodies
    });
  }
});

// Example: trigger a form submission that calls multiple APIs
await page.getByRole('button', { name: 'Submit Order' }).click();
await page.waitForLoadState('networkidle');

// Expected flow:
// POST /api/orders → 201 Created
// GET /api/orders/{id} → 200 OK
// POST /api/payments → 200 OK
// GET /api/orders/{id}/status → 200 OK

const flowValidation = [
  { step: 1, method: 'POST', url: '/api/orders', expectedStatus: 201 },
  { step: 2, method: 'GET', url: '/api/orders/', expectedStatus: 200 },
  { step: 3, method: 'POST', url: '/api/payments', expectedStatus: 200 },
  { step: 4, method: 'GET', url: '/api/orders/', expectedStatus: 200 },
];

const consoleLogs = [];
page.on('console', (msg) => {
  consoleLogs.push({
    type: msg.type(),
    text: msg.text(),
    stack: msg.stack(),
    timestamp: Date.now(),
  });
});

const errors = consoleLogs.filter(l => l.type === 'error');
const warnings = consoleLogs.filter(l => l.type === 'warning');
const logs = consoleLogs.filter(l => l.type === 'log');

// When needed, inject custom debug logging
await page.evaluate(() => {
  const originalFetch = window.fetch;
  window.fetch = function(...args) {
    console.log('[DEBUG FETCH]', args[0]);
    return originalFetch.apply(this, args);
  };
});

// Execute each branch separately with screenshots
// Branch 1: Happy path
await page.getByRole('button', { name: 'Continue' }).click();
await page.waitForURL('**/step-2');
await page.screenshot({ path: 'evidence/control-flow/happy-path-step-2.png' });

// Branch 2: Validation error path
// (re-navigate or reset state)
await page.getByRole('textbox').fill('invalid-value');
await page.getByRole('button', { name: 'Submit' }).click();
await page.waitForSelector('.error-message');
await page.screenshot({ path: 'evidence/control-flow/validation-error.png' });

const browsers = ['chromium', 'firefox', 'webkit'];
const results = {};

for (const browserType of browsers) {
  const browser = await playwright[browserType].launch();
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.screenshot({ path: `evidence/cross-browser/${browserType}.png` });
  await browser.close();
}

const contrastResults = await page.evaluate(() => {
  const elements = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, span, a, button, .card-text, .subtitle, .label'));
  return elements.map(el => {
    const style = getComputedStyle(el);
    const fg = style.color;
    const bg = style.backgroundColor;
    const fontSize = parseFloat(style.fontSize);
    const fontWeight = parseInt(style.fontWeight);
    const opacity = parseFloat(style.opacity);
    const ratio = computeContrast(fg, bg);
    return {
      tag: el.tagName,
      text: el.textContent.trim().substring(0, 50),
      contrastRatio: ratio.toFixed(2),
      passesAA: ratio >= 4.5,
      passesAALarge: ratio >= 3.0,
      fontSize: fontSize,
      fontWeight: fontWeight,
      opacity: opacity,
      effectiveContrast: (ratio * opacity).toFixed(2),
    };
  });
});

const fontResults = await page.evaluate(() => {
  const elements = document.querySelectorAll('p, span, a, button, .card-text');
  return Array.from(elements).map(el => {
    const style = getComputedStyle(el);
    return {
      text: el.textContent.trim().substring(0, 50),
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      fontFamily: style.fontFamily,
      lineHeight: style.lineHeight,
      letterSpacing: style.letterSpacing,
      isLegible: parseFloat(style.fontSize) >= 14,
    };
  });
});

// Elements with opacity < 0.8 multiply their effective contrast
const opacityIssues = await page.evaluate(() => {
  const elements = document.querySelectorAll('.subtitle, .label, .hint, .placeholder');
  return Array.from(elements).map(el => {
    const style = getComputedStyle(el);
    const opacity = parseFloat(style.opacity);
    if (opacity < 0.8) {
      const rawContrast = computeContrast(style.color, style.backgroundColor);
      return {
        text: el.textContent.trim().substring(0, 50),
        opacity: opacity,
        rawContrast: rawContrast.toFixed(2),
        effectiveContrast: (rawContrast * opacity).toFixed(2),
        passesAA: (rawContrast * opacity) >= 4.5,
      };
    }
    return null;
  }).filter(Boolean);
});

// For status indicators, badges, and color-coded elements
const colorBlindnessCheck = await page.evaluate(() => {
  const badges = document.querySelectorAll('.badge, .status, [class*="color-"], [class*="bg-"]');
  return Array.from(badges).map(el => {
    const style = getComputedStyle(el);
    const bg = style.backgroundColor;
    const color = style.color;
    // Check if color is the primary visual cue
    const isColorOnly = el.children.length === 0 ||
      Array.from(el.children).every(c => c.tagName === 'I' || c.tagName === 'SVG');
    return {
      text: el.textContent.trim().substring(0, 50),
      bgColor: bg,
      textColor: color,
      isColorOnly: isColorOnly,
      // Simulate deuteranopia (most common color blindness)
      deuteranopiaSafe: checkDeuteranopia(bg, color),
    };
  });
});

const polishCheck = await page.evaluate(() => {
  const results = {
    alignmentIssues: [],
    typographyHierarchy: {},
    borderShadowConsistency: {},
    deadSpace: [],
    overflowIssues: [],
  };

  // Check alignment consistency
  const cards = document.querySelectorAll('.card, [class*="card"]');
  cards.forEach(card => {
    const rect = card.getBoundingClientRect();
    if (rect.width > 600) {
      const marginLeft = parseFloat(getComputedStyle(card).marginLeft);
      const marginRight = parseFloat(getComputedStyle(card).marginRight);
      if (Math.abs(marginLeft - marginRight) > 10) {
        results.alignmentIssues.push({
          element: card.className,
          text: card.textContent.trim().substring(0, 50),
          marginLeft, marginRight,
        });
      }
    }
  });

  // Check typography hierarchy
  const headings = document.querySelectorAll('h1, h2, h3');
  const sizes = Array.from(headings).map(h => parseFloat(getComputedStyle(h).fontSize));
  results.typographyHierarchy = {
    h1: sizes[0],
    h2: sizes[1],
    h3: sizes[2],
    isHierarchical: sizes[0] >= sizes[1] >= sizes[2],
  };

  // Check for overflow and truncation
  document.querySelectorAll('*').forEach(el => {
    const style = getComputedStyle(el);
    if (style.overflow === 'hidden' && el.scrollHeight > el.clientHeight) {
      results.overflowIssues.push({
        tag: el.tagName,
        class: el.className,
        text: el.textContent.trim().substring(0, 50),
      });
    }
  });

  return results;
});

// Test at multiple breakpoints with screenshots
const breakpoints = [
  { width: 375, height: 667, name: 'mobile-small' },   // iPhone SE
  { width: 768, height: 1024, name: 'tablet' },         // iPad
  { width: 1280, height: 720, name: 'desktop' },        // Desktop
];

for (const bp of breakpoints) {
  await page.setViewportSize(bp.width, bp.height);
  await page.screenshot({
    path: `evidence/accessibility/mobile-${bp.name}.png`,
    fullPage: true
  });

  // Check mobile-specific issues
  const mobileIssues = await page.evaluate(() => {
    const touchTargets = document.querySelectorAll('button, a, [role="button"]');
    const smallTargets = Array.from(touchTargets).filter(t => {
      const rect = t.getBoundingClientRect();
      return rect.width < 44 || rect.height < 44; // Apple min touch target
    });
    return {
      count: smallTargets.length,
      examples: smallTargets.slice(0, 5).map(t => ({
        tag: t.tagName,
        width: t.getBoundingClientRect().width,
        height: t.getBoundingClientRect().height,
        text: t.textContent.trim().substring(0, 30),
      })),
    };
  });
}

const colorPairs = await page.evaluate(() => {
  const elements = document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, span, a, button, li, td, th, label, .badge, .status, [class*="card"], [class*="panel"]');
  return Array.from(elements).map(el => {
    const style = getComputedStyle(el);
    return {
      text: el.textContent.trim().substring(0, 60),
      tag: el.tagName,
      className: el.className.substring(0, 60),
      textColor: style.color,
      bgColor: style.backgroundColor,
      fontSize: parseFloat(style.fontSize),
      fontWeight: parseInt(style.fontWeight),
      opacity: parseFloat(style.opacity),
      isLarge: parseFloat(style.fontSize) >= 22 || (parseFloat(style.fontSize) >= 18 && parseInt(style.fontWeight) >= 700),
    };
  });
});

const contrastResults = colorPairs.map(pair => {
  const ratio = computeContrast(pair.textColor, pair.bgColor);
  let threshold = 4.5; // AA normal text
  let thresholdName = 'AA_normal (4.5:1)';
  if (pair.isLarge) {
    threshold = 3.0;
    thresholdName = 'AA_large (3:1)';
  }
  if (pair.tag === 'svg' || pair.tag === 'i' || pair.tag === 'path' ||
      pair.className.includes('icon') || pair.className.includes('border')) {
    threshold = 3.0;
    thresholdName = 'UI_component (3:1)';
  }
  return {
    ...pair,
    contrastRatio: ratio.toFixed(2),
    threshold: threshold,
    thresholdName: thresholdName,
    passes: ratio >= threshold,
    effectiveRatio: (ratio * pair.opacity).toFixed(2),
    effectivePasses: (ratio * pair.opacity) >= threshold,
  };
});

const darkThemeIssues = await page.evaluate(() => {
  const issues = [];

  // Check background colors for pure black
  document.querySelectorAll('*').forEach(el => {
    const bg = getComputedStyle(el).backgroundColor;
    const bgRgb = parseRgb(bg);
    if (bgRgb && bgRgb.r === 0 && bgRgb.g === 0 && bgRgb.b === 0) {
      issues.push({
        type: 'pure_black_bg',
        severity: 'high',
        element: el.tagName,
        class: el.className.substring(0, 40),
        text: el.textContent.trim().substring(0, 50),
        message: 'Pure black background (#000) causes eye strain. Use #212529, #0a0f12, or #111820 instead.',
      });
    }

    // Check text colors for pure white on dark bg
    const textColor = getComputedStyle(el).color;
    const textRgb = parseRgb(textColor);
    if (textRgb && textRgb.r === 255 && textRgb.g === 255 && textRgb.b === 255 && bgRgb) {
      const bgLuminance = luminance(bgRgb);
      if (bgLuminance < 0.2) {
        issues.push({
          type: 'pure_white_text',
          severity: 'high',
          element: el.tagName,
          class: el.className.substring(0, 40),
          text: el.textContent.trim().substring(0, 50),
          message: 'Pure white text (#fff) on dark bg causes glare. Use #dee2e6 or #e0e8f0 instead.',
        });
      }
    }
  });

  // Check status indicators
  document.querySelectorAll('.badge, .status, [class*="badge"], [class*="status"]').forEach(el => {
    const bg = getComputedStyle(el).backgroundColor;
    const parentBg = getComputedStyle(el.parentElement).backgroundColor;
    const ratio = computeContrast(bg, parentBg);
    const isColorOnly = el.children.length === 0 ||
      Array.from(el.children).every(c => c.tagName === 'I' || c.tagName === 'SVG');
    if (ratio < 3.0) {
      issues.push({
        type: 'invisible_indicator',
        severity: 'high',
        element: el.tagName,
        class: el.className.substring(0, 40),
        text: el.textContent.trim().substring(0, 50),
        contrastRatio: ratio.toFixed(2),
        message: `Status indicator contrast ${ratio.toFixed(2)}:1 — below 3:1 minimum. Invisible to low-vision users.`,
      });
    }
    if (isColorOnly) {
      issues.push({
        type: 'color_only_indicator',
        severity: 'medium',
        element: el.tagName,
        class: el.className.substring(0, 40),
        message: 'Status indicator relies solely on color — not accessible to color-blind users. Add icon or text label.',
      });
    }
  });

  // Check semantic colors against dark-mode references
  const darkRefs = {
    success: { r: 117, g: 183, b: 152 },  // #75b798
    danger: { r: 234, g: 134, b: 143 },   // #ea868f
    warning: { r: 255, g: 218, b: 106 },  // #ffda6a
  };
  document.querySelectorAll('[class*="success"], [class*="danger"], [class*="warning"]').forEach(el => {
    const bg = getComputedStyle(el).backgroundColor;
    const bgRgb = parseRgb(bg);
    if (bgRgb && bgRgb.r < 100 && bgRgb.g < 100 && bgRgb.b < 100) {
      issues.push({
        type: 'semantic_color_too_dark',
        severity: 'medium',
        element: el.tagName,
        class: el.className.substring(0, 40),
        message: 'Semantic color too dark for dark mode. Use lighter variants: success #75b798, danger #ea868f, warning #ffda6a.',
      });
    }
  });

  return issues;
});

const paletteAudit = await page.evaluate(() => {
  // Collect all distinct background colors
  const backgrounds = new Set();
  document.querySelectorAll('.card, [class*="card"], [class*="panel"], body, .container, .section').forEach(el => {
    const bg = getComputedStyle(el).backgroundColor;
    if (bg && bg !== 'rgba(0, 0, 0, 0)') backgrounds.add(bg);
  });

  // Convert to HSL and check lightness progression
  const bgHSL = Array.from(backgrounds).map(c => {
    const rgb = parseRgb(c);
    return rgbToHsl(rgb.r, rgb.g, rgb.b);
  }).sort((a, b) => a.l - b.l);

  // Check if lightness steps are consistent (5-8% apart)
  const stepDiffs = bgHSL.slice(1).map((hsl, i) => Math.abs(hsl.l - bgHSL[i].l));
  const consistentSteps = stepDiffs.every(d => d >= 5 && d <= 20);

  // Check text hierarchy (body text off-white, secondary ~75% opacity, muted ~50%)
  const textColors = new Set();
  document.querySelectorAll('p, span, .card-text, .body').forEach(el => {
    const color = getComputedStyle(el).color;
    if (color && color !== 'rgba(0, 0, 0, 0)') textColors.add(color);
  });

  return {
    distinctBackgrounds: backgrounds.size,
    bgLightnessSteps: bgHSL.map(h => h.l.toFixed(1)),
    lightnessConsistent: consistentSteps,
    distinctTextColors: textColors.size,
    hasOffWhiteBody: Array.from(textColors).some(c => {
      const rgb = parseRgb(c);
      return rgb.r >= 200 && rgb.r <= 230;
    }),
  };
});

const scorecard = {
  contrastPassRate: contrastResults.filter(r => r.passes).length / contrastResults.length,
  contrastFailCount: contrastResults.filter(r => !r.passes).length,
  darkThemeIssueCount: darkThemeIssues.length,
  paletteCoherent: paletteAudit.lightnessConsistent,
  hasOffWhiteBody: paletteAudit.hasOffWhiteBody,
  statusIndicatorIssues: darkThemeIssues.filter(i => i.type === 'invisible_indicator').length,
  colorOnlyIndicatorIssues: darkThemeIssues.filter(i => i.type === 'color_only_indicator').length,
};
